import assert from 'node:assert/strict';
import { Session } from './src/session.js';

const idleTimers = { schedule() { throw new Error('unexpected retry'); } };
let calls = 0;
const offline = new Session({ timers: idleTimers, queryFn({ signal }) { calls++; assert.equal(signal.aborted, false); return 'should-not-run'; } }, { online: false });
const h = offline.subscribe('stop:central', { networkMode: 'online', refetchOnReconnect: false });
assert.deepEqual(offline.snapshot('stop:central'), { status: 'pending', fetchStatus: 'paused', data: null });
offline.unsubscribe(h);
assert.deepEqual(offline.snapshot('stop:central'), { status: 'pending', fetchStatus: 'idle', data: null });
offline.online(true);
await Promise.resolve();
assert.equal(calls, 0);

let resolve;
const started = new Session({ timers: idleTimers, queryFn() { calls++; return new Promise(r => { resolve = r; }); } });
const active = started.subscribe('stop:central');
started.unsubscribe(active);
resolve('cached stop');
await Promise.resolve();
assert.deepEqual(started.snapshot('stop:central'), { status: 'success', fetchStatus: 'idle', data: 'cached stop' });

let sharedCalls = 0;
const shared = new Session({ timers: idleTimers, queryFn() { sharedCalls++; return 'shared'; } }, { online: false });
const first = shared.subscribe('stop:central');
shared.subscribe('stop:central');
shared.unsubscribe(first);
shared.online(true);
await Promise.resolve();
assert.equal(sharedCalls, 1);
console.log('lifecycle assertions passed');
